-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.lock_card_state(p_note_guid text, p_ord integer, p_deck_id text)
 RETURNS public.card_states
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  current_row public.card_states;
begin
  select * into current_row from public.card_states
   where user_id = auth.uid() and note_guid = p_note_guid and ord = p_ord
   for update;
  return current_row;
end;
$function$;

grant execute on function public.lock_card_state(p_note_guid text, p_ord integer, p_deck_id text) to service_role;
